    font-weight: normal;
    line-height: 40px;
    letter-spacing: 0px;
    color: var(--grey-blue-surface-g-700);
    display: flex;
    align-items: center;
    cursor: pointer;
    margin-bottom: 10px;
    .tab-list-lot-t{
        flex: 1;
        margin-left: 20px;
    }
    img{
        width: 20px;
